using System.Collections.Generic;

/// <summary>Los textos de las cinemáticas del Cap. 4 (tabla de subtítulos, ES/EN).</summary>
public static partial class MontajeDeLosCapitulos
{
    private static IEnumerable<(string clave, string es, string en)> TextosDeCineCap4() => new[]
    {
        ("CAP4_ESTELA_01", "¿Y tú quién eres? ¿Otra pobre princesita perdida en el bosque?", "And who are you? Another poor little princess lost in the woods?"),
        ("CAP4_ESTELA_02", "Me llamo Will. Busco a la hechicera Estela.", "My name's Will. I'm looking for the sorceress Estela."),
        ("CAP4_ESTELA_03", "La tienes delante. Y si vienes a que convierta a alguien en sapo, ya no lo hago. El último acabó con vestido.", "You're looking at her. And if you've come to have someone turned into a toad, I don't do that anymore. The last one ended up in a dress."),
        ("CAP4_ESTELA_04", "Impresionante.", "Impressive."),
        ("CAP4_ESTELA_05", "Vengo a que leas esto.", "I came so you could read this."),
        ("CAP4_ESTELA_06", "Runas de sometimiento. El collar es la jaula; las runas, la orden. Y cada aro tiene una llave.", "Runes of subjugation. The collar is the cage; the runes, the command. And every collar has a key."),
        ("CAP4_ESTELA_07", "El monstruo no era tu demonio. Es quien le puso el aro.", "The monster wasn't your demon. It's whoever put the collar on him."),
        ("CAP4_ESTELA_08", "Hay una magia que no sale de ti: la sacas de otro. La llaman oscura porque la fuerza no es tuya.", "There's a kind of magic that doesn't come from you: you take it from someone else. They call it dark because the strength isn't yours."),
        ("CAP4_ESTELA_09", "No acepto aprendices.", "I don't take apprentices."),
        ("CAP4_ESTELA_10", "No vengo a aprender. Vengo a pedir ayuda. En la costa hay más animales con aro; lo he apuntado todo.", "I'm not here to learn. I'm here to ask for help. There are more collared animals on the coast; I wrote it all down."),
        ("CAP4_ESTELA_11", "…Alguien está haciendo muchos.", "…Someone is making a lot of them."),
        ("CAP4_ESTELA_12", "Te ayudo. Eso es hacerte un favor. Y ya me lo cobraré.", "I'll help you. That's me doing you a favour. And I'll collect on it."),
        ("CAP4_MANANA_01", "«ENTRENAMIENTO DEL FUTURO GRAN HECHICERO». ¿Por qué «futuro» va tan pequeño?", "\"TRAINING OF THE FUTURE GREAT WIZARD\". Why is \"future\" so small?"),
        ("CAP4_MANANA_02", "Porque es lo que más lejos te queda.", "Because it's the part you're furthest from."),
        ("CAP4_MANANA_03", "El fuego no es una cosa sola: puede empujar, cortar, iluminar o calentar.", "Fire isn't just one thing: it can push, cut, light or warm."),
        ("CAP4_MANANA_04", "Hoy aprendes a protegerte. Y a proteger a otro, que es más difícil.", "Today you learn to protect yourself. And to protect someone else, which is harder."),
        ("CAP4_MANANA_05", "Vale. ¿Por dónde empiezo?", "All right. Where do I start?"),
        ("CAP4_CAMPANA_01", "¿Ves la campana? Llega hasta ella y tócala.", "See the bell? Get to it and ring it."),
        ("CAP4_CAMPANA_02", "Las figuras de barro son gente. No se chamusca a la gente.", "The clay figures are people. You don't scorch people."),
        ("CAP4_CAMPANA_03", "¿Y tú qué vas a hacer?", "And what are you going to do?"),
        ("CAP4_CAMPANA_04", "Molestarte.", "Get in your way."),
        ("CAP4_FIGURA_01", "¡Esa se cae!", "That one's falling!"),
        ("CAP4_FIGURA_02", "Eso no te lo he enseñado yo.", "I didn't teach you that."),
        ("CAP4_FIGURA_03", "Ni yo sé qué ha sido.", "I don't know what it was either."),
        ("CAP4_FIGURA_04", "Esta se parece a Eldran.", "This one looks like Eldran."),
        ("CAP4_FIGURA_05", "Le faltan orejas. Ya está.", "It needs ears. There."),
        ("CAP4_FIGURA_06", "¿Y esa de la capucha?", "And the one with the hood?"),
        ("CAP4_FIGURA_07", "Alguien que nos observa desde ayer. Lo noto en la nuca.", "Someone who's been watching us since yesterday. I can feel it on the back of my neck."),
        ("CAP4_FIGURA_08", "Lista. Más de lo que creía.", "Sharp. Sharper than I thought."),
        ("CAP4_GOLEM_05", "¿Tú no tienes miedo nunca?", "Aren't you ever scared?"),
        ("CAP4_GOLEM_01", "El miedo se aprende a llevar. Y si no, siempre te queda irte a vivir a un bosque.", "You learn to carry fear. And if not, you can always go and live in a forest."),
        ("CAP4_GOLEM_02", "¿Eso hiciste tú?", "Is that what you did?"),
        ("CAP4_GOLEM_03", "Eso no se pregunta.", "You don't ask that."),
        ("CAP4_GOLEM_04", "¡Al suelo! ¡Viene de la tierra!", "Get down! It's coming out of the ground!"),
        ("CAP4_TRAS_GOLEM_01", "Ya está… ¿Estás bien?", "It's over… Are you all right?"),
        ("CAP4_TRAS_GOLEM_02", "Tengo los dedos como corteza. Tú sangras por la nariz.", "My fingers are like bark. Your nose is bleeding."),
        ("CAP4_TRAS_GOLEM_03", "Mira esto, entre las rocas… Por un momento he visto una cara.", "Look at this, among the rocks… For a moment I saw a face."),
        ("CAP4_TRAS_GOLEM_04", "Un cristal de invocación. Alguien ha llamado a ese gólem.", "A summoning crystal. Someone called that golem."),
        ("CAP4_TRAS_GOLEM_05", "No volver a utilizar seres vivos.", "Never use living beings again."),
        ("CAP4_MANZANA_01", "Cenizas todavía calientes. Alguien ha dormido aquí esta noche.", "Ashes still warm. Someone slept here last night."),
        ("CAP4_MANZANA_07", "¿Estás bien? Apóyate en mí.", "Are you all right? Lean on me."),
        ("CAP4_MANZANA_02", "Puedo sola.", "I can manage."),
        ("CAP4_MANZANA_03", "Ya lo sé.", "I know."),
        ("CAP4_MANZANA_04", "Es la última manzana. Está harinosa.", "It's the last apple. It's mealy."),
        ("CAP4_MANZANA_05", "Pues a medias.", "Then we'll share it."),
        ("CAP4_MANZANA_06", "Hacía mucho que nadie se ponía delante de mí. Gracias, idiota.", "It's been a long time since anyone stood in front of me. Thanks, idiot."),
        ("CAP4_BIFURCACION_01", "Por el río llegamos antes.", "We'll get there faster along the river."),
        ("CAP4_BIFURCACION_02", "Por los pinos no nos mojamos. Y el mapa dice pinos.", "Through the pines we won't get wet. And the map says pines."),
        ("CAP4_BIFURCACION_03", "Ni un paso más.", "Not one more step."),
        ("CAP4_BIFURCACION_04", "Tranquila. Solo quería ver lo que lleváis.", "Easy. I only wanted to see what you're carrying."),
        ("CAP4_BIFURCACION_05", "Enséñaselo. No se lo des.", "Show it to him. Don't give it to him."),
        ("CAP4_BIFURCACION_06", "Sujeción. Obediencia. Vínculo. Es un aro de los malos.", "Restraint. Obedience. Bond. It's one of the bad ones."),
        ("CAP4_BIFURCACION_07", "Me llamo Liam. Voy al Reino.", "My name's Liam. I'm going to the Kingdom."),
        ("CAP4_BIFURCACION_08", "Nosotros también. Podemos viajar juntos hasta allí.", "So are we. We can travel there together."),
        ("CAP4_BIFURCACION_09", "El hierro no lo toca nadie.", "Nobody touches the iron."),
        ("CAP4_BIFURCACION_10", "Por el río, entonces. Hay un vado.", "The river, then. There's a ford."),
        ("CAP4_BIFURCACION_11", "¡Mi bota! ¡Se me ha salido en el vado!", "My boot! It came off in the ford!"),
        ("CAP4_BOTA_01", "Toma. Estaba enganchada entre dos ramas.", "Here. It was caught between two branches."),
        ("CAP4_BOTA_02", "El vado cubría más de lo que parecía.", "The ford was deeper than it looked."),
        ("CAP4_BOTA_03", "Por los pinos no nos habríamos mojado.", "We wouldn't have got wet through the pines."),
        ("CAP4_BOTA_04", "Tampoco salía en el mapa que alguien iría a por mi bota.", "The map didn't say anyone would go after my boot, either."),
    };
}
